import{_ as n,c as a,G as s,J as e,C as t,a4 as o,V as p,b as r,B as i,D as l}from"./chunks/framework.DULpp8DO.js";const c=JSON.parse('{"title":"上下文工程实战：Context Window 的极限运营","description":"从 prompt engineering 到 context engineering 的范式迁移：拆解上下文的构成、context rot 的机理，以及 just-in-time 检索、compaction、结构化笔记、subagent 隔离等核心策略的实战细节。","frontmatter":{"title":"上下文工程实战：Context Window 的极限运营","date":"2026-06-18T00:00:00.000Z","categories":["技术分享"],"tags":["上下文工程","Context Engineering","LLM","Prompt Engineering","Agent"],"description":"从 prompt engineering 到 context engineering 的范式迁移：拆解上下文的构成、context rot 的机理，以及 just-in-time 检索、compaction、结构化笔记、subagent 隔离等核心策略的实战细节。","articleGPT":"上下文窗口是 agent 最稀缺的资源，本文系统讲解\\"上下文工程\\"这套极限运营方法论。文章首先分析上下文的四大组成部分（系统指令、工具定义、记忆、实时工作上下文）各自的膨胀原因，引入 context rot 与\\"注意力预算\\"心智模型；然后逐个拆解核心策略：just-in-time context 用工具按需检索替代预加载、compaction 的触发时机与信息保留策略、NOTES.md/CLAUDE.md 式结构化笔记、subagent 隔离脏活。文中给出 Anthropic 的方法论解读、一个长任务的上下文预算数字示例，以及把整个文件塞上下文、工具结果不截断等典型反模式，帮你像运营内存一样运营上下文。","cover":"https://lsky.rz15.cn/i/2026/11/19/6afed421b4e82.png","top":null,"share":true,"delete":false,"head":[["link",{"rel":"canonical","href":"https://ruo.ge/posts/2026-06/20260618"}]]},"headers":[],"relativePath":"posts/2026-06/20260618.md","filePath":"posts/2026-06/20260618.md","lastUpdated":1795486093000}');const u=n({name:"posts/2026-06/20260618.md"},[["render",function(n,c,u,g,d,m){const b=p("Mermaid");return r(),a("div",null,[c[1]||(c[1]=s('<h1 id="上下文工程实战-context-window-的极限运营" tabindex="-1">上下文工程实战：Context Window 的极限运营 <a class="header-anchor" href="#上下文工程实战-context-window-的极限运营" aria-label="Permalink to &quot;上下文工程实战：Context Window 的极限运营&quot;">​</a></h1><h2 id="从-prompt-engineering-到-context-engineering" tabindex="-1">从 Prompt Engineering 到 Context Engineering <a class="header-anchor" href="#从-prompt-engineering-到-context-engineering" aria-label="Permalink to &quot;从 Prompt Engineering 到 Context Engineering&quot;">​</a></h2><p>2023 年我们谈 prompt engineering：怎么把一句话措辞改得更有效。2024 年谈 RAG：怎么把检索到的文档拼进 prompt。到了 agent 时代，问题升级了——模型面对的不再是&quot;一条 prompt&quot;，而是一个持续增长、多来源混合、随时可能爆炸的<strong>上下文流</strong>：系统指令常驻、几十个工具 schema 常驻、CLAUDE.md 常驻，然后每一轮对话、每一次工具调用都在往里追加内容。</p><p>范式随之迁移。Anthropic 在《Effective context engineering for AI agents》一文中给出的定义很精准：上下文工程是为系统每一步<strong>精选恰当的信息子集</strong>的艺术与科学。注意两个关键词：&quot;每一步&quot;——它是一个动态过程而非一次性拼装；&quot;恰当的子集&quot;——不是越多越好，而是要精挑。</p><p>这和传统软件里的内存管理惊人地相似。上下文窗口就是你的内存条：容量有限、访问有代价（token 成本与延迟）、放太多垃圾会拖慢一切。上下文工程师的工作，本质上是在给 LLM 做极限的内存运营。</p><h2 id="上下文的四块构成-以及它们各自怎么膨胀的" tabindex="-1">上下文的四块构成，以及它们各自怎么膨胀的 <a class="header-anchor" href="#上下文的四块构成-以及它们各自怎么膨胀的" aria-label="Permalink to &quot;上下文的四块构成，以及它们各自怎么膨胀的&quot;">​</a></h2><p>一个典型编码 agent 的上下文由四部分组成：</p><p><strong>1. 系统指令。</strong> 行为规则、输出格式、安全约束。它的问题在于<strong>只增不减</strong>：每次发现模型某个行为不对，最省事的方案就是往系统提示里加一条规则。一年下来几千 token 的系统提示很常见。</p><p><strong>2. 工具定义。</strong> 每个 MCP server 动辄注册十几个工具，每个工具的 schema（名称、描述、参数说明）几百上千 token。接上 GitHub、Slack、数据库三套 MCP 后，仅工具定义就可能占掉两三万 token——<strong>在任何一次推理开始之前</strong>，预算已经被吃掉一大块。工具数量还会反向影响选择准确率（工具超过一定数量后，模型选错的概率明显上升），这是双重惩罚。</p><p><strong>3. 记忆。</strong> CLAUDE.md、用户偏好、历史会话的沉淀。设计良好的记忆是分层的、按需加载的；设计不良的记忆是一个无限增长的 README。</p><p><strong>4. 实时工作上下文。</strong> 对话历史 + 工具调用与结果。这是膨胀最快的一块：一次文件读取几万 token，一次失败的搜索几千 token，几轮下来窗口见底。</p><p>前三块是&quot;固定开销&quot;，第四块是&quot;动态开销&quot;。上下文工程的所有策略，都是围绕&quot;压缩固定开销、控制动态开销&quot;展开的。</p><h2 id="context-rot-为什么塞得越多-模型越笨" tabindex="-1">Context Rot：为什么塞得越多，模型越笨 <a class="header-anchor" href="#context-rot-为什么塞得越多-模型越笨" aria-label="Permalink to &quot;Context Rot：为什么塞得越多，模型越笨&quot;">​</a></h2><p>很多人有一个直觉错误：上下文窗口 200K，那就尽量多放信息，反正&quot;放进去模型总能看到&quot;。实际情况相反——<strong>塞得越多，模型对每条信息的注意力越稀薄</strong>。</p><p>这个现象被称为 context rot（上下文腐烂）。机制上可以这样理解：注意力是软性的，模型要在所有 token 之间分配&quot;注意力预算&quot;。上下文从 1 万 token 涨到 10 万，模型要在 10 倍的干扰中定位和组合信息，检索精度、指令遵循度、推理质量都会退化。长上下文基准测试里&quot;大海捞针&quot;成绩很好，但真实多步任务的表现衰减要严重得多——因为真实任务需要的不是单点检索，而是跨远距离的信息组合。</p><p>一个好用的心智模型：<strong>把上下文当成血量条</strong>。健康区间大概是窗口的前一半；超过某个阈值后模型开始&quot;贫血&quot;——变得健忘、机械、容易犯低级错误；打满时濒临崩溃。运营目标是让上下文长期维持在健康区，而不是挑战极限。</p>',16)),(r(),e(o,null,{default:t((()=>[i(b,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E5%B9%B2%E5%87%80%E4%B8%8A%E4%B8%8B%E6%96%87%3Cbr%2F%3E%E5%81%A5%E5%BA%B7%E5%8C%BA%5D%20--%3E%20B%5B%E5%A4%9A%E8%BD%AE%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%3Cbr%2F%3E%E7%BB%93%E6%9E%9C%E6%8C%81%E7%BB%AD%E8%BF%BD%E5%8A%A0%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%99%AA%E5%A3%B0%E7%B4%AF%E7%A7%AF%3Cbr%2F%3E%E6%B3%A8%E6%84%8F%E5%8A%9B%E7%A8%80%E9%87%8A%5D%0A%20%20%20%20C%20--%3E%20D%7B%E9%80%BC%E8%BF%91%E9%98%88%E5%80%BC%7D%0A%20%20%20%20D%20--%20%E6%98%AF%20--%3E%20E%5B%E5%B9%B2%E9%A2%84%E6%89%8B%E6%AE%B5%3Cbr%2F%3Ecompaction%20%2F%20%E9%9A%94%E7%A6%BB%20%2F%20%E6%B8%85%E7%90%86%5D%0A%20%20%20%20E%20--%3E%20A%0A%20%20%20%20D%20--%20%E5%90%A6%20--%3E%20F%5B%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%E4%BB%BB%E5%8A%A1%5D%0A%20%20%20%20F%20--%3E%20B%0A"})])),fallback:t((()=>c[0]||(c[0]=[l(" Loading... ")]))),_:1})),c[2]||(c[2]=s('<h2 id="策略一-just-in-time-context——按需检索-拒绝预加载" tabindex="-1">策略一：Just-in-Time Context——按需检索，拒绝预加载 <a class="header-anchor" href="#策略一-just-in-time-context——按需检索-拒绝预加载" aria-label="Permalink to &quot;策略一：Just-in-Time Context——按需检索，拒绝预加载&quot;">​</a></h2><p>传统 RAG 思维是&quot;提前把可能相关的资料都塞进上下文&quot;。agent 时代的正确姿势是反过来的：<strong>上下文里只放指针，需要时用工具取</strong>。</p><p>具体做法：</p><ul><li>上下文里只保留文件路径、函数名、接口签名这些&quot;地址&quot;，用 Read/Grep 现场取货。Claude Code 不预读任何代码，模型先 Glob 找文件、再精确 Read 需要的部分，就是这个原则的体现。</li><li>大文件永远分页读，读完当前任务所需的那一段就走，不要&quot;顺便把整个文件读了备用&quot;。</li><li>agentic search 优于一次性检索：模型可以多轮迭代搜索——第一轮 Grep 没找到就换关键词再来，这是传统 RAG 单次向量检索做不到的。</li></ul><p>代价是延迟和工具调用次数增加，但换来的是每一轮推理面对的都是<strong>小而相关</strong>的上下文。用轮次换质量，在 agent 场景里几乎总是划算的。</p><h2 id="策略二-compaction——对话的垃圾回收" tabindex="-1">策略二：Compaction——对话的垃圾回收 <a class="header-anchor" href="#策略二-compaction——对话的垃圾回收" aria-label="Permalink to &quot;策略二：Compaction——对话的垃圾回收&quot;">​</a></h2><p>上下文逼近阈值时，最有效的干预是 compaction：把历史对话交给模型做一次结构化摘要，用摘要替换原始内容，会话继续。</p><p>两个关键决策点：</p><p><strong>什么时候触发？</strong> 不要等打满。Claude Code 的实践是在接近窗口上限约 92% 时自动触发。更主动的做法是在任务的自然断点（完成一个子任务、通过一轮测试）主动 compact，因为这时信息结构最完整，摘要质量最高。</p><p><strong>摘要保留什么？</strong> 这是 compaction 成败的核心。好的保留结构大致是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 任务目标与当前进度        # 使命不能丢</span></span>\n<span class="line"><span>2. 关键决策及其理由          # 为什么选方案 A 不选 B</span></span>\n<span class="line"><span>3. 涉及的文件路径与函数名    # 工作现场坐标</span></span>\n<span class="line"><span>4. 未解决的问题与待办        # 下一步的起点</span></span>\n<span class="line"><span>5. 用户明确表达过的偏好约束  # 边界条件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>而对话中的寒暄、失败的尝试过程、中间搜索结果，都可以丢弃——注意&quot;失败的尝试&quot;要丢弃但<strong>结论要留</strong>：&quot;X 方案会导致循环导入，已放弃&quot;这一句话，是几万 token 试错换来的，必须浓缩保留。</p><p>Compaction 是有损压缩，必然丢细节。工程上的补救是：<strong>在 compact 前把不可再生的关键状态写入外部文件</strong>（见策略三），摘要只是兜底，文件才是真相。</p><h2 id="策略三-结构化笔记——notes-md-模式" tabindex="-1">策略三：结构化笔记——NOTES.md 模式 <a class="header-anchor" href="#策略三-结构化笔记——notes-md-模式" aria-label="Permalink to &quot;策略三：结构化笔记——NOTES.md 模式&quot;">​</a></h2><p>Claude Code 官方博客推荐过一个朴素而有效的模式：让 agent 在长任务开始时创建一个 <code>NOTES.md</code>（或类似的临时文件），持续写入关键状态；每完成一个阶段就更新它。这样即使 compaction 丢失了对话细节，agent 重新读一下笔记文件就能恢复工作现场。</p><p>这个模式可以推广为三层记忆体系：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作记忆  -&gt; NOTES.md 等临时文件，记录当前任务的现场状态</span></span>\n<span class="line"><span>短期记忆  -&gt; 会话内的 compaction 摘要，跨阶段保活</span></span>\n<span class="line"><span>长期记忆  -&gt; CLAUDE.md / memory 目录，跨会话沉淀</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>要点是<strong>结构化</strong>：笔记要按固定 schema 写（目标/决策/文件/待办），而不是自由日记。结构化内容在恢复时可以被精确定位读取——只需要&quot;待办&quot;一节时，Grep 一下就够，不必整篇重读。</p><h2 id="策略四-subagent-隔离——让脏活死在子上下文里" tabindex="-1">策略四：Subagent 隔离——让脏活死在子上下文里 <a class="header-anchor" href="#策略四-subagent-隔离——让脏活死在子上下文里" aria-label="Permalink to &quot;策略四：Subagent 隔离——让脏活死在子上下文里&quot;">​</a></h2><p>subagent 是上下文工程的&quot;物理隔离&quot;手段：主 agent 派生一个子 agent 去干会产生大量中间输出的活（全库搜索、读十几个文件做调研、跑批量验证），子 agent 在自己独立的上下文里消化所有噪声，<strong>只把几百 token 的结论回传主上下文</strong>。</p><p>一个直观的算术：主 agent 自己做一次全库调研，中间结果约 5 万 token 进主上下文；派 subagent 做，主上下文只增加约 500 token 的结论摘要。差距 100 倍，而且这些中间噪声如果留在主上下文，之后每一轮推理都要背着它们跑。</p><p>适用判断很简单：<strong>这个活动的主产物是结论还是细节？</strong> 要结论的（&quot;这个 bug 在哪个模块&quot;）适合外包；要细节的（&quot;编辑这个函数&quot;）必须留在主上下文亲手做。把 Edit 这类需要精确上下文的操作外包给 subagent，等于让一个没看过现场的人写代码，效果会很差。</p><h2 id="一个长任务的上下文预算示例" tabindex="-1">一个长任务的上下文预算示例 <a class="header-anchor" href="#一个长任务的上下文预算示例" aria-label="Permalink to &quot;一个长任务的上下文预算示例&quot;">​</a></h2><p>假设 200K 窗口跑一个&quot;给支付模块加重试机制&quot;的重构任务，预算可以这样分配：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>固定开销（约 25K）：</span></span>\n<span class="line"><span>  系统提示              4K</span></span>\n<span class="line"><span>  工具 schema（20 个）  12K</span></span>\n<span class="line"><span>  CLAUDE.md（分层后）    6K</span></span>\n<span class="line"><span>  少量用户偏好           3K</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>动态开销（约 90K，健康区内滚动使用）：</span></span>\n<span class="line"><span>  任务规划与 todo        3K</span></span>\n<span class="line"><span>  定位阶段（Grep/Glob）  10K</span></span>\n<span class="line"><span>  精读相关代码（3-4 个文件分页读） 30K</span></span>\n<span class="line"><span>  修改与验证（Edit + 跑测试）      25K</span></span>\n<span class="line"><span>  失败重试余量           10K</span></span>\n<span class="line"><span>  记录 NOTES.md 开销      2K</span></span>\n<span class="line"><span>  缓冲余量               10K</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>剩余约 85K 为安全余量，接近阈值则触发 compaction 后继续。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>可以算一笔账：如果不做任何运营，把 5 个相关文件全文（约 100K）一次性塞进上下文，加上固定开销，初始状态就已经吃掉 125K，再跑两轮测试就触发 compaction——整个会话将在低质量上下文里挣扎。<strong>预算思维决定了任务是顺畅推进还是一路救火。</strong></p><h2 id="常见的上下文反模式" tabindex="-1">常见的上下文反模式 <a class="header-anchor" href="#常见的上下文反模式" aria-label="Permalink to &quot;常见的上下文反模式&quot;">​</a></h2><p>最后收拢一批我在真实项目里反复看到的错误做法：</p><p><strong>1. 把整个文件塞进上下文。&quot;保险起见全部读进来&quot;。</strong> 一个 3000 行的文件约 6 万 token，塞进去后模型的注意力被无关代码稀释，反而更容易漏掉真正相关的几行。正确做法：先看结构（Grep 函数签名），再分页精读目标区域。</p><p><strong>2. 工具结果不截断。</strong> 一条 <code>cat app.log</code> 吐回 50 万 token，一条失控的搜索打穿窗口。所有工具输出必须设上限，超长结果要么截断、要么落盘成文件让 agent 按需读取。</p><p><strong>3. 多轮累积噪声。</strong> 失败的尝试、重复的搜索、过时的代码片段全部留在历史里，从不清理。旧版本代码片段尤其危险——模型可能把它当成当前事实继续引用。该 compact 就 compact，该隔离就隔离。</p><p><strong>4. 把记忆当仓库。</strong> CLAUDE.md 写成千行的百科全书，每轮全量注入。记忆应该是&quot;指针 + 索引&quot;，大块知识放文件里按需读。</p><p><strong>5. 工具无限注册。</strong> MCP server 接了七八套，工具 schema 常驻 3 万 token，模型选择工具的准确率同步下滑。砍到当前任务真正需要的十来个。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>上下文工程说到底是一种<strong>稀缺资源运营</strong>的功夫：窗口是内存，注意力是 CPU 时间片，每一轮推理都是一次资源分配决策。prompt engineering 关注&quot;怎么说&quot;，context engineering 关注&quot;此刻模型应该看见什么&quot;——后者才是 agent 系统里真正决定成败的那一层。当你发现自家 agent 越跑越笨，别急着换模型，先看看它的上下文里都堆了些什么。</p>',35))])}]]);export{c as __pageData,u as default};
